from pathlib import Path
from collections import Counter
import re
from datetime import date

base = Path('/app/logs')
ref = date(2025, 8, 12)
severities = ('ERROR', 'WARNING', 'INFO')
periods = {
    'today': lambda d: d == ref,
    'last_7_days': lambda d: (ref - d).days in range(7),
    'last_30_days': lambda d: (ref - d).days in range(30),
    'month_to_date': lambda d: d.year == ref.year and d.month == ref.month and d <= ref,
    'total': lambda d: True,
}
counts = {p: Counter() for p in periods}
name_re = re.compile(r'^(\d{4}-\d{2}-\d{2})_.+\.log$')
for path in base.iterdir():
    if not path.is_file():
        continue
    match = name_re.match(path.name)
    if not match:
        continue
    d = date.fromisoformat(match.group(1))
    content = path.read_text(errors='replace')
    for line in content.splitlines():
        for severity in severities:
            # Severity tokens as standalone words, so e.g. ERROR_CODE is excluded.
            if re.search(rf'\b{severity}\b', line):
                for period, includes in periods.items():
                    if includes(d):
                        counts[period][severity] += 1

rows = ['period,severity,count']
for period in periods:
    rows.extend(f'{period},{severity},{counts[period][severity]}' for severity in severities)
Path('/app/summary.csv').write_text('\n'.join(rows) + '\n')
print('\n'.join(rows))
